export const PANEL_INDEX_HTML = "<!doctype html>\n<html lang=\"pl\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Panel — Entuzjaści Hopkostki</title>\n  <link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><text y='.9em' font-size='90'>🫓</text></svg>\">\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <div id=\"login-gate\" class=\"login-gate\">\n    <form id=\"login-form\" class=\"login-card\">\n      <div class=\"logo big\">🫓</div>\n      <h2>Panel — Entuzjaści Hopkostki</h2>\n      <p class=\"muted\">Podaj hasło panelu. Znajdziesz je w Supabase → Edge Functions → Secrets → <code>PANEL_PASSWORD</code>, albo — jeśli nikt go tam nie ustawił — bot wygenerował je sam (zapytaj administratora / sprawdź stan bota).</p>\n      <input type=\"password\" id=\"login-password\" placeholder=\"Hasło panelu\" autocomplete=\"current-password\" required>\n      <p class=\"error-text\" id=\"login-error\"></p>\n      <button type=\"submit\" class=\"btn primary\" id=\"login-submit\">Zaloguj</button>\n    </form>\n  </div>\n\n  <div id=\"app\" class=\"layout hidden\">\n    <aside class=\"sidebar\">\n      <div class=\"brand\">\n        <img id=\"bot-avatar\" class=\"avatar\" alt=\"\" hidden>\n        <span id=\"bot-logo\" class=\"logo\">🫓</span>\n        <div>\n          <strong id=\"bot-name\">Hopkostki Bot</strong>\n          <small id=\"bot-state\" class=\"state offline\">łączenie…</small>\n        </div>\n      </div>\n      <nav id=\"nav\">\n        <a href=\"#pulpit\" data-view=\"pulpit\">📊 <span>Pulpit</span></a>\n        <a href=\"#ustawienia\" data-view=\"ustawienia\">⚙️ <span>Ustawienia</span></a>\n        <a href=\"#uprawnienia\" data-view=\"uprawnienia\">🔑 <span>Uprawnienia</span></a>\n        <a href=\"#embedy\" data-view=\"embedy\">🎨 <span>Wygląd embedów</span></a>\n        <a href=\"#ostrzezenia\" data-view=\"ostrzezenia\">⚠️ <span>Ostrzeżenia</span></a>\n        <a href=\"#sprawy\" data-view=\"sprawy\">🗂️ <span>Sprawy</span></a>\n        <a href=\"#bany\" data-view=\"bany\">⛔ <span>Tymczasowe bany</span></a>\n      </nav>\n      <a class=\"side-link\" href=\"https://supabase.com/dashboard/project/ucjmbdogtzztrkorqzjq\" target=\"_blank\" rel=\"noopener\">☁️ Supabase</a>\n      <button type=\"button\" class=\"side-link\" id=\"logout-btn\">🚪 Wyloguj</button>\n    </aside>\n\n    <main>\n      <div id=\"conn-error\" class=\"banner hidden\"></div>\n      <!-- PULPIT -->\n      <section id=\"view-pulpit\" class=\"view\">\n        <header class=\"view-head\">\n          <h2>Pulpit</h2>\n          <p class=\"muted\">Szybki podgląd bota i serwera.</p>\n        </header>\n        <div class=\"grid two\">\n          <div class=\"card row-card\">\n            <img id=\"guild-icon\" class=\"avatar lg\" alt=\"\" hidden>\n            <div>\n              <div class=\"label\">Serwer</div>\n              <div id=\"guild-name\" class=\"big-text\">—</div>\n              <div id=\"guild-members\" class=\"muted\"></div>\n            </div>\n          </div>\n          <div class=\"card row-card\">\n            <div>\n              <div class=\"label\">Bot na Supabase</div>\n              <div id=\"status-text\" class=\"big-text\">—</div>\n              <div id=\"status-extra\" class=\"muted\"></div>\n            </div>\n          </div>\n        </div>\n        <div class=\"card\">\n          <div class=\"card-head\">\n            <h3>🔌 Połączenie z Discordem</h3>\n            <button type=\"button\" class=\"btn ghost small\" id=\"setup-run\">↻ Sprawdź i zarejestruj komendy</button>\n          </div>\n          <ul class=\"checklist\" id=\"setup-list\"></ul>\n        </div>\n        <div id=\"stats\" class=\"stats\"></div>\n        <div class=\"card\">\n          <h3>Ostatnie sprawy</h3>\n          <div class=\"table-wrap\"><table class=\"table\" id=\"recent-table\"></table></div>\n        </div>\n      </section>\n\n      <!-- USTAWIENIA -->\n      <section id=\"view-ustawienia\" class=\"view\">\n        <header class=\"view-head\">\n          <h2>Ustawienia</h2>\n          <p class=\"muted\">Zmiany zapisujesz przyciskiem na dole ekranu. Działają od razu, bez restartu bota.</p>\n        </header>\n        <div class=\"grid two\">\n          <div class=\"card\">\n            <h3>📢 Kanały</h3>\n            <label class=\"field\">\n              <span>Kanał logów moderacji</span>\n              <select data-path=\"modLogChannelId\" data-channel-select=\"none\"></select>\n              <small>Pełne szczegóły każdej akcji: punkty, status DM, link do wiadomości.</small>\n            </label>\n            <label class=\"field\">\n              <span>Kanał ogłoszeń o karach</span>\n              <select data-path=\"announceChannelId\" data-channel-select=\"command\"></select>\n              <small>Domyślnie embed pojawia się tam, gdzie użyto komendy.</small>\n            </label>\n          </div>\n          <div class=\"card\">\n            <h3>🛡️ Role moderatorów</h3>\n            <p class=\"muted small\">Osoby z tymi rolami mogą używać komend bota. Administratorzy i osoby z uprawnieniami Discorda (np. „Banowanie członków”) mają dostęp zawsze. Jeśli rola nie ma uprawnień Discorda, zezwól jej też na komendy w <em>Ustawienia serwera → Integracje</em>.</p>\n            <div id=\"roles-list\" class=\"roles-list\"></div>\n          </div>\n          <div class=\"card\">\n            <h3>✉️ Wiadomości</h3>\n            <label class=\"toggle\"><input type=\"checkbox\" data-path=\"mentionTarget\"><span></span>Oznaczaj ukaranego użytkownika na kanale</label>\n            <label class=\"toggle\"><input type=\"checkbox\" data-path=\"dmUsers\"><span></span>Wysyłaj DM do ukaranego użytkownika</label>\n            <label class=\"toggle\"><input type=\"checkbox\" data-path=\"dmShowModerator\"><span></span>Pokazuj w DM, kto nałożył karę</label>\n            <label class=\"field\">\n              <span>Dopisek w DM (np. jak się odwołać)</span>\n              <textarea data-path=\"appealText\" rows=\"3\" maxlength=\"1500\"></textarea>\n            </label>\n          </div>\n          <div class=\"card\">\n            <h3>🫓 Reakcja na odpowiedzi</h3>\n            <p class=\"muted small\">Gdy ktoś odpowie (reply) na wiadomość bota o karze, bot doda pod jego odpowiedzią tę reakcję.</p>\n            <label class=\"toggle\"><input type=\"checkbox\" data-path=\"replyReaction.enabled\"><span></span>Włączone</label>\n            <label class=\"field\">\n              <span>Emoji (zwykłe lub własne w formacie <code>&lt;:nazwa:id&gt;</code>)</span>\n              <input type=\"text\" data-path=\"replyReaction.emoji\" maxlength=\"100\">\n            </label>\n            <div class=\"chips\" id=\"emoji-picks\"></div>\n          </div>\n        </div>\n        <div class=\"card\">\n          <div class=\"card-head\">\n            <h3>🟢 Status i opisy bota</h3>\n            <span class=\"muted small\" id=\"gateway-line\"></span>\n          </div>\n          <p class=\"muted small\">Bot łączy się z Discordem co minutę (gateway), dzięki czemu świeci na zielono i pokazuje poniższe opisy — zmieniają się co ustawioną liczbę sekund.</p>\n          <div class=\"grid two tight\">\n            <label class=\"field\"><span>Status</span>\n              <select data-path=\"presence.status\">\n                <option value=\"online\">🟢 Dostępny</option>\n                <option value=\"idle\">🌙 Zaraz wracam</option>\n                <option value=\"dnd\">⛔ Nie przeszkadzać</option>\n              </select>\n            </label>\n            <label class=\"field\"><span>Zmiana opisu co (sekundy, min. 15)</span><input type=\"number\" min=\"15\" max=\"3600\" data-path=\"presence.rotateSeconds\"></label>\n          </div>\n          <label class=\"toggle\"><input type=\"checkbox\" data-path=\"presence.enabled\"><span></span>Pokazuj opisy w statusie</label>\n          <div class=\"table-wrap\"><table class=\"table compact\" id=\"activities-table\"></table></div>\n          <div class=\"placeholders\">\n            <button type=\"button\" class=\"btn ghost\" id=\"add-activity\">+ Dodaj opis</button>\n            <span class=\"muted small\">Zmienne:</span>\n            <div class=\"chips\" id=\"presence-chips\"></div>\n          </div>\n        </div>\n        <div class=\"card\">\n          <h3>🔒 Hasło panelu</h3>\n          <p class=\"muted small\" id=\"password-status\">—</p>\n          <form id=\"password-form\" class=\"grid two tight\">\n            <label class=\"field\"><span>Nowe hasło (min. 8 znaków)</span><input type=\"password\" id=\"password-new\" autocomplete=\"new-password\" minlength=\"8\"></label>\n            <label class=\"field\"><span>Powtórz nowe hasło</span><input type=\"password\" id=\"password-repeat\" autocomplete=\"new-password\" minlength=\"8\"></label>\n            <button type=\"submit\" class=\"btn primary\" id=\"password-submit\">Zmień hasło</button>\n          </form>\n        </div>\n      </section>\n\n      <!-- UPRAWNIENIA -->\n      <section id=\"view-uprawnienia\" class=\"view\">\n        <header class=\"view-head\">\n          <h2>Uprawnienia</h2>\n          <p class=\"muted\">Domyślnie o dostępie decydują uprawnienia Discorda danej roli (np. „Banowanie członków”) oraz lista ról moderatorów z zakładki Ustawienia. Tutaj możesz ograniczyć pojedynczą komendę do wybranych ról — niezależnie od uprawnień Discorda.</p>\n        </header>\n        <div class=\"card\">\n          <h3>🎛️ Nadpisania dla komend</h3>\n          <div id=\"permission-commands\" class=\"perm-commands\"></div>\n        </div>\n        <div class=\"card\">\n          <h3>📋 Kto może użyć jakiej komendy — podgląd na żywo</h3>\n          <p class=\"muted small\">Liczone z ról serwera, uprawnień Discorda, listy moderatorów i nadpisań powyżej. Rola <code>@everyone</code> i role zarządzane przez integracje nie są pokazane.</p>\n          <div class=\"table-wrap\"><table class=\"table compact\" id=\"permission-matrix\"></table></div>\n        </div>\n      </section>\n\n      <!-- EMBEDY -->\n      <section id=\"view-embedy\" class=\"view\">\n        <header class=\"view-head\">\n          <h2>Wygląd embedów</h2>\n          <p class=\"muted\">Każda komenda ma własny styl. Podgląd odświeża się na żywo.</p>\n        </header>\n        <div class=\"tabs\" id=\"embed-tabs\"></div>\n        <div class=\"grid editor\">\n          <div class=\"card\">\n            <div class=\"grid two tight\">\n              <label class=\"field\"><span>Kolor</span>\n                <div class=\"color-row\"><input type=\"color\" id=\"embed-color-picker\"><input type=\"text\" data-embed-field=\"color\" maxlength=\"7\"></div>\n              </label>\n              <label class=\"field\"><span>Emoji</span><input type=\"text\" data-embed-field=\"emoji\" maxlength=\"100\"></label>\n            </div>\n            <h4>Na kanale</h4>\n            <label class=\"field\"><span>Tytuł</span><input type=\"text\" data-embed-field=\"title\" maxlength=\"250\"></label>\n            <label class=\"field\"><span>Opis</span><textarea data-embed-field=\"description\" rows=\"2\"></textarea></label>\n            <h4>Wiadomość prywatna (DM)</h4>\n            <label class=\"field\"><span>Tytuł</span><input type=\"text\" data-embed-field=\"dmTitle\" maxlength=\"250\"></label>\n            <label class=\"field\"><span>Opis</span><textarea data-embed-field=\"dmDescription\" rows=\"2\"></textarea></label>\n            <div class=\"placeholders\">\n              <span class=\"muted small\">Kliknij, żeby wstawić zmienną:</span>\n              <div class=\"chips\" id=\"placeholder-chips\"></div>\n            </div>\n            <button type=\"button\" class=\"btn ghost\" id=\"embed-reset\">↺ Przywróć domyślny wygląd tej akcji</button>\n          </div>\n          <div class=\"previews\">\n            <div class=\"preview-label\">Podgląd na kanale</div>\n            <div class=\"discord\" id=\"preview-channel\"></div>\n            <div class=\"preview-label\">Podgląd w DM</div>\n            <div class=\"discord\" id=\"preview-dm\"></div>\n          </div>\n        </div>\n      </section>\n\n      <!-- OSTRZEŻENIA -->\n      <section id=\"view-ostrzezenia\" class=\"view\">\n        <header class=\"view-head\">\n          <h2>Ostrzeżenia</h2>\n          <p class=\"muted\">Punkty widzi tylko moderacja. Każde ostrzeżenie ma własne odliczanie do wygaśnięcia.</p>\n        </header>\n        <div class=\"grid two\">\n          <div class=\"card\">\n            <h3>⚙️ Ustawienia ostrzeżeń</h3>\n            <label class=\"field\"><span>Domyślna liczba punktów za ostrzeżenie</span><input type=\"number\" min=\"1\" max=\"100\" data-path=\"warns.defaultPoints\"></label>\n            <label class=\"field\"><span>Po ilu dniach ostrzeżenie wygasa (0 = nigdy)</span><input type=\"number\" min=\"0\" max=\"3650\" data-path=\"warns.expiryDays\">\n              <small>Dotyczy nowych ostrzeżeń — już nadane zachowują swoje odliczanie.</small></label>\n            <label class=\"toggle\"><input type=\"checkbox\" data-path=\"warns.showPointsToUser\"><span></span>Pokazuj punkty ukaranemu (kanał + DM)</label>\n          </div>\n          <div class=\"card\">\n            <h3>🚨 Automatyczne kary</h3>\n            <label class=\"toggle\"><input type=\"checkbox\" data-path=\"escalation.enabled\"><span></span>Włącz automatyczne kary po przekroczeniu progu</label>\n            <p class=\"muted small\">„Alert” tylko pinguje role moderatorów na kanale logów — decyzję podejmujecie sami.</p>\n            <div class=\"table-wrap\"><table class=\"table compact\" id=\"rules-table\"></table></div>\n            <button type=\"button\" class=\"btn ghost\" id=\"add-rule\">+ Dodaj próg</button>\n          </div>\n        </div>\n        <div class=\"card\">\n          <div class=\"card-head\">\n            <h3>📋 Aktywne ostrzeżenia</h3>\n            <input type=\"search\" id=\"warn-search\" placeholder=\"Szukaj po nicku lub ID…\">\n          </div>\n          <div id=\"warn-users\"></div>\n        </div>\n      </section>\n\n      <!-- SPRAWY -->\n      <section id=\"view-sprawy\" class=\"view\">\n        <header class=\"view-head\">\n          <h2>Sprawy</h2>\n          <p class=\"muted\">Historia wszystkich akcji moderacyjnych.</p>\n        </header>\n        <div class=\"card\">\n          <div class=\"filters\">\n            <input type=\"search\" id=\"case-search\" placeholder=\"Nick lub ID użytkownika…\">\n            <select id=\"case-type\">\n              <option value=\"\">Wszystkie typy</option>\n              <option value=\"ban\">Bany</option>\n              <option value=\"unban\">Unbany</option>\n              <option value=\"kick\">Kicki</option>\n              <option value=\"timeout\">Timeouty</option>\n              <option value=\"untimeout\">Zdjęcia timeoutu</option>\n              <option value=\"warn\">Ostrzeżenia</option>\n            </select>\n          </div>\n          <div class=\"table-wrap\"><table class=\"table\" id=\"cases-table\"></table></div>\n          <div class=\"pager\" id=\"cases-pager\"></div>\n        </div>\n      </section>\n\n      <!-- TYMCZASOWE BANY -->\n      <section id=\"view-bany\" class=\"view\">\n        <header class=\"view-head\">\n          <h2>Tymczasowe bany</h2>\n          <p class=\"muted\">Bot sam zdejmie bana, gdy skończy się odliczanie.</p>\n        </header>\n        <div class=\"card\">\n          <div class=\"table-wrap\"><table class=\"table\" id=\"bans-table\"></table></div>\n        </div>\n      </section>\n    </main>\n  </div>\n\n  <div id=\"savebar\" class=\"savebar hidden\">\n    <span>Masz niezapisane zmiany</span>\n    <div>\n      <button type=\"button\" class=\"btn ghost\" id=\"discard\">Odrzuć</button>\n      <button type=\"button\" class=\"btn success\" id=\"save\">Zapisz zmiany</button>\n    </div>\n  </div>\n  <div id=\"toast\" class=\"toast\"></div>\n\n  <script src=\"app.js\"></script>\n</body>\n</html>\n";

export const PANEL_APP_JS = "'use strict';\n\n// ---------- Stałe ----------\nconst MINUTE = 60_000;\nconst HOUR = 60 * MINUTE;\nconst DAY = 24 * HOUR;\n\nconst ACTION_LABELS = { ban: 'Ban', unban: 'Unban', kick: 'Kick', timeout: 'Timeout', untimeout: 'Untimeout', warn: 'Ostrzeżenie' };\nconst CASE_LABELS = { ...ACTION_LABELS, untimeout: 'Zdjęcie timeoutu' };\nconst SLASH_NAMES = { ban: '/ban', unban: '/unban', kick: '/kick', timeout: '/timeout', untimeout: '/untimeout', warn: '/warn dodaj' };\nconst UNIT_FORMS = {\n  m: ['minuta', 'minuty', 'minut'],\n  h: ['godzina', 'godziny', 'godzin'],\n  d: ['dzień', 'dni', 'dni'],\n  w: ['tydzień', 'tygodnie', 'tygodni'],\n  mo: ['miesiąc', 'miesiące', 'miesięcy'],\n};\nconst UNIT_LABELS = { m: 'Minuty', h: 'Godziny', d: 'Dni', w: 'Tygodnie', mo: 'Miesiące' };\nconst RULE_ACTIONS = { alert: 'Alert 🔔', timeout: 'Timeout', kick: 'Kick', ban: 'Ban' };\nconst PLACEHOLDERS = ['{uzytkownik}', '{nick}', '{moderator}', '{moderatorNick}', '{powod}', '{czas}', '{serwer}', '{sprawa}', '{typ}'];\nconst ACTIVITY_LABELS = { custom: '💬 Własny opis', playing: '🎮 Gra w', listening: '🎧 Słucha', watching: '📺 Ogląda', competing: '🏆 Rywalizuje w' };\nconst PRESENCE_PLACEHOLDERS = ['{czlonkowie}', '{online}', '{serwer}', '{ostrzezenia}', '{sprawy}'];\nconst EMOJI_PICKS = ['🫓', '🍞', '👀', '✅', '🔥', '💀', '🫡', '😂'];\nconst VIEWS = ['pulpit', 'ustawienia', 'uprawnienia', 'embedy', 'ostrzezenia', 'sprawy', 'bany'];\nconst PANEL_PASSWORD_KEY = 'hopkostki-panel-password';\nconst SAMPLE = { targetId: '111', target: 'hurownik_og', modId: '222', mod: 'dfgbh65', reason: 'Wielokrotne łamanie zasad' };\n\nconst state = {\n  config: null,\n  draft: null,\n  defaults: null,\n  guild: { channels: [], roles: [] },\n  status: null,\n  view: 'pulpit',\n  embedAction: 'ban',\n  lastField: null,\n  casesPage: 1,\n  warnUsers: [],\n  openWarnUsers: new Set(),\n  reloadPending: false,\n  commandMeta: null,\n  lastActivityInput: null,\n};\n\n// ---------- Narzędzia ----------\nconst $ = (sel, root = document) => root.querySelector(sel);\nconst $$ = (sel, root = document) => [...root.querySelectorAll(sel)];\nconst clone = (value) => JSON.parse(JSON.stringify(value));\nconst esc = (value) =>\n  String(value ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' })[c]);\nconst pad = (n) => String(n).padStart(2, '0');\n\nfunction getPath(obj, path) {\n  return path.split('.').reduce((o, key) => o?.[key], obj);\n}\nfunction setPath(obj, path, value) {\n  const keys = path.split('.');\n  const last = keys.pop();\n  keys.reduce((o, key) => o[key], obj)[last] = value;\n}\n\nfunction plural(n, [one, few, many]) {\n  if (n === 1) return one;\n  const n10 = n % 10;\n  const n100 = n % 100;\n  return n10 >= 2 && n10 <= 4 && (n100 < 12 || n100 > 14) ? few : many;\n}\nconst formatDuration = (amount, unit) => `${amount} ${plural(amount, UNIT_FORMS[unit] ?? ['', '', ''])}`;\n\nfunction fullDate(ms) {\n  return new Date(ms).toLocaleString('pl-PL', { day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' });\n}\nfunction shortDate(ms) {\n  return new Date(ms).toLocaleString('pl-PL', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });\n}\nfunction relTime(ms) {\n  const diff = ms - Date.now();\n  const abs = Math.abs(diff);\n  let text;\n  if (abs >= 30 * DAY) text = formatDuration(Math.round(abs / (30 * DAY)), 'mo');\n  else if (abs >= DAY) text = formatDuration(Math.round(abs / DAY), 'd');\n  else if (abs >= HOUR) text = formatDuration(Math.round(abs / HOUR), 'h');\n  else text = formatDuration(Math.max(1, Math.round(abs / MINUTE)), 'm');\n  return diff >= 0 ? `za ${text}` : `${text} temu`;\n}\nfunction formatCountdown(ms) {\n  if (ms <= 0) return 'wygasa…';\n  const total = Math.floor(ms / 1000);\n  const d = Math.floor(total / 86400);\n  const h = Math.floor((total % 86400) / 3600);\n  const m = Math.floor((total % 3600) / 60);\n  const s = total % 60;\n  return `${d ? `${d} ${plural(d, UNIT_FORMS.d)} ` : ''}${pad(h)}:${pad(m)}:${pad(s)}`;\n}\n\n// Hasło żyje tylko w tej karcie (sessionStorage) — panel jest hostowany razem z botem na Supabase,\n// więc wywołania idą tym samym originem; dlatego ścieżka jest WZGLĘDNA (bez wiodącego \"/\"): dzięki temu\n// działa niezależnie od tego, pod jakim prefiksem funkcja jest zamontowana (…/hopkostki-bot/panel/…).\nfunction getPanelPassword() {\n  try {\n    return sessionStorage.getItem(PANEL_PASSWORD_KEY) || '';\n  } catch {\n    return '';\n  }\n}\nfunction setPanelPassword(value) {\n  try {\n    sessionStorage.setItem(PANEL_PASSWORD_KEY, value);\n  } catch {\n    /* prywatna karta / zablokowany storage — hasło trzeba będzie wpisać ponownie po odświeżeniu */\n  }\n}\nfunction clearPanelPassword() {\n  try {\n    sessionStorage.removeItem(PANEL_PASSWORD_KEY);\n  } catch {}\n}\n\nasync function api(path, options = {}) {\n  const res = await fetch(path.replace(/^\\/+/, ''), {\n    ...options,\n    headers: { 'Content-Type': 'application/json', 'x-panel-password': getPanelPassword(), ...(options.headers ?? {}) },\n  });\n  const data = await res.json().catch(() => ({}));\n  if (res.status === 401) {\n    clearPanelPassword();\n    showLoginGate(data.error || 'Złe hasło panelu.');\n    throw new Error(data.error || 'Wymagane logowanie.');\n  }\n  if (!res.ok) {\n    const message = data.error || `Błąd ${res.status}`;\n    if ([500, 502, 503].includes(res.status)) showConnectionError(message);\n    throw new Error(message);\n  }\n  hideConnectionError();\n  return data;\n}\n\nlet toastTimer = null;\nfunction toast(message, type = 'ok') {\n  const el = $('#toast');\n  el.textContent = message;\n  el.className = `toast show ${type === 'error' ? 'error' : ''}`;\n  clearTimeout(toastTimer);\n  toastTimer = setTimeout(() => el.classList.remove('show'), 3000);\n}\n\n// ---------- Błędy połączenia z botem ----------\nfunction showConnectionError(message) {\n  const el = $('#conn-error');\n  el.innerHTML = `<strong>Brak połączenia z botem.</strong> ${esc(message)}`;\n  el.classList.remove('hidden');\n}\nfunction hideConnectionError() {\n  $('#conn-error').classList.add('hidden');\n}\n\n// ---------- Logowanie ----------\nfunction showLoginGate(message) {\n  const gate = $('#login-gate');\n  const wasHidden = gate.classList.contains('hidden');\n  gate.classList.remove('hidden');\n  $('#app').classList.add('hidden');\n  if (message) $('#login-error').textContent = message;\n  if (wasHidden) {\n    $('#login-password').value = '';\n    $('#login-password').focus();\n  }\n}\nfunction revealApp() {\n  $('#login-gate').classList.add('hidden');\n  $('#app').classList.remove('hidden');\n  $('#login-error').textContent = '';\n}\n\n$('#login-form').addEventListener('submit', async (event) => {\n  event.preventDefault();\n  setPanelPassword($('#login-password').value);\n  $('#login-submit').disabled = true;\n  try {\n    await api('/status'); // samo wywołanie sprawdza, czy hasło jest poprawne\n    await init();\n  } catch (error) {\n    $('#login-error').textContent = error.message;\n  } finally {\n    $('#login-submit').disabled = false;\n  }\n});\n\n$('#logout-btn').addEventListener('click', () => {\n  clearPanelPassword();\n  showLoginGate();\n});\n\n// ---------- Start ----------\nlet started = false;\nasync function start() {\n  const [{ config, defaults }, guild, { commands }] = await Promise.all([\n    api('/config'),\n    api('/guild').catch(() => ({ channels: [], roles: [] })),\n    api('/commands').catch(() => ({ commands: [] })),\n  ]);\n  state.config = config;\n  state.draft = clone(config);\n  state.defaults = defaults;\n  state.guild = guild;\n  state.commandMeta = commands;\n  revealApp();\n  renderConfigUi();\n  route();\n  if (!started) {\n    started = true;\n    refreshStatus();\n    setInterval(refreshStatus, 15_000);\n    setInterval(tick, 1000);\n  }\n}\n\nasync function init() {\n  try {\n    await start();\n  } catch (error) {\n    // Hasło zostało już wyczyszczone i pokazany ekran logowania przez api() — nie ma sensu tu dobijać.\n    if (getPanelPassword()) {\n      showConnectionError(error.message);\n      setTimeout(init, 10_000);\n    }\n  }\n}\n\nfunction boot() {\n  if (getPanelPassword()) init();\n  else showLoginGate();\n}\n\n// ---------- Nawigacja ----------\nfunction route() {\n  const hash = location.hash.slice(1);\n  state.view = VIEWS.includes(hash) ? hash : 'pulpit';\n  $$('.view').forEach((v) => v.classList.toggle('active', v.id === `view-${state.view}`));\n  $$('#nav a').forEach((a) => a.classList.toggle('active', a.dataset.view === state.view));\n  if (state.view === 'pulpit') refreshStatus();\n  if (state.view === 'ostrzezenia') loadWarns();\n  if (state.view === 'sprawy') loadCases();\n  if (state.view === 'bany') loadBans();\n  if (state.view === 'embedy') renderPreview();\n  if (state.view === 'uprawnienia') renderPermissions();\n}\nwindow.addEventListener('hashchange', route);\n\n// ---------- Status / pulpit ----------\nasync function refreshStatus() {\n  if (!state.config) return;\n  let status;\n  try {\n    status = await api('/status');\n  } catch {\n    $('#bot-state').textContent = 'panel offline';\n    $('#bot-state').className = 'state offline';\n    return;\n  }\n  const wasReady = state.status?.ready;\n  state.status = status;\n\n  $('#bot-state').textContent = status.ready ? 'działa na Supabase' : 'wymaga konfiguracji';\n  $('#bot-state').className = `state ${status.ready ? 'online' : 'offline'}`;\n  if (status.bot) {\n    $('#bot-name').textContent = status.bot.tag;\n    $('#bot-avatar').src = status.bot.avatar;\n    $('#bot-avatar').hidden = false;\n    $('#bot-logo').hidden = true;\n  }\n  if (status.guild) {\n    $('#guild-name').textContent = status.guild.name;\n    $('#guild-members').textContent = `${status.guild.memberCount ?? \"?\"} członków • ID ${status.guild.id}`;\n    if (status.guild.icon) {\n      $('#guild-icon').src = status.guild.icon;\n      $('#guild-icon').hidden = false;\n    }\n  } else {\n    $('#guild-name').textContent = status.ready ? 'Bot nie jest na żadnym serwerze' : '—';\n  }\n  const lastCron = status.cron?.at;\n  $('#status-text').textContent = status.ready ? '🟢 Działa' : '🔴 Nie działa';\n  $('#status-extra').textContent = status.ready\n    ? `Ostatnie zadania okresowe: ${lastCron ? relTime(lastCron) : 'jeszcze nie było'}`\n    : status.error ?? 'Sprawdź sekrety w Supabase.';\n  renderSetup(status);\n  renderGatewayLine(status.gateway);\n\n  const s = status.stats;\n  const cards = [\n    ['Sprawy łącznie', s.cases, '#5865f2'],\n    ['Aktywne ostrzeżenia', s.activeWarns, state.config.actions.warn.color],\n    ['Tymczasowe bany', s.tempBans, state.config.actions.ban.color],\n    ['Bany', s.byType.ban ?? 0, state.config.actions.ban.color],\n    ['Timeouty', s.byType.timeout ?? 0, state.config.actions.timeout.color],\n    ['Kicki', s.byType.kick ?? 0, state.config.actions.kick.color],\n  ];\n  $('#stats').innerHTML = cards\n    .map(([label, value, color]) => `<div class=\"stat\" style=\"--accent:${esc(color)}\"><b>${value}</b><span>${label}</span></div>`)\n    .join('');\n  $('#recent-table').innerHTML = casesTable(status.recent);\n\n  // Bot właśnie się połączył — dociągamy kanały i role do formularzy.\n  if (status.ready && (!wasReady || !state.guild.channels.length)) {\n    state.guild = await api('/guild');\n    renderChannelSelects();\n    renderRoles();\n    if (state.view === 'uprawnienia') renderPermissions();\n  }\n  if (state.view === 'embedy') renderPreview();\n  renderPasswordStatus(status);\n}\n\nconst gatewayOk = (gateway) => Boolean(gateway?.startedAt && !gateway.error && Date.now() - gateway.startedAt < 3 * MINUTE);\n\nfunction renderSetup(status) {\n  const setup = status.setup ?? {};\n  const cronAt = status.cron?.at;\n  const items = [\n    [setup.tokenConfigured, 'Token bota (DISCORD_TOKEN) ustawiony w sekretach Supabase', setup.tokenConfigured ? '' : 'Supabase → Edge Functions → Secrets → dodaj DISCORD_TOKEN.'],\n    [status.ready, 'Bot widzi serwer', status.ready ? status.guild?.name : status.error],\n    [\n      setup.endpoint && setup.endpoint === setup.selfUrl,\n      'Discord wysyła komendy do Supabase (Interactions Endpoint URL)',\n      setup.endpointError ? `Błąd: ${setup.endpointError}` : setup.selfUrl,\n    ],\n    [Boolean(setup.commandsRegisteredAt), 'Komendy slash zarejestrowane', setup.commandsRegisteredAt ? `ostatnio ${relTime(setup.commandsRegisteredAt)}` : 'zrobi się samo w ciągu minuty'],\n    [cronAt && Date.now() - cronAt < 3 * MINUTE, 'Zadania okresowe (pg_cron co 30 s)', cronAt ? `ostatnio ${relTime(cronAt)}` : 'jeszcze nie uruchomione'],\n    [\n      gatewayOk(status.gateway),\n      'Status „online” i opisy (gateway co minutę)',\n      status.gateway?.error ?? (status.gateway?.startedAt ? `ostatnia sesja ${relTime(status.gateway.startedAt)}${status.gateway.mode === 'resume' ? ' (wznowiona)' : ''}` : 'uruchomi się w ciągu minuty'),\n    ],\n  ];\n  $('#setup-list').innerHTML = items\n    .map(([done, label, hint]) => `<li><span>${done ? '✅' : '⏳'}</span><div>${esc(label)}${hint ? `<small>${esc(hint)}</small>` : ''}</div></li>`)\n    .join('');\n}\n\n$('#setup-run').addEventListener('click', async () => {\n  $('#setup-run').disabled = true;\n  try {\n    await api('/setup', { method: 'POST' });\n    toast('Komendy zarejestrowane ✅');\n  } catch (error) {\n    toast(error.message, 'error');\n  }\n  $('#setup-run').disabled = false;\n  refreshStatus();\n});\n\nfunction caseBadge(entry) {\n  const color = state.config.actions[entry.type]?.color ?? '#99aab5';\n  const label = entry.type === 'ban' && entry.duration ? 'Tempban' : CASE_LABELS[entry.type] ?? entry.type;\n  return `<span class=\"badge\" style=\"background:${esc(color)}\">${esc(label)}</span>`;\n}\n\nfunction casesTable(items) {\n  if (!items.length) return '<tr><td class=\"empty\">Brak spraw. Spokojnie jak na Hopkostkach. 🫓</td></tr>';\n  const rows = items\n    .map((c) => {\n      const duration = c.duration ? formatDuration(c.duration.amount, c.duration.unit) : c.type === 'ban' ? 'perm.' : '—';\n      const expiry = c.expiresAt ? `<span class=\"note\">do ${esc(shortDate(c.expiresAt))}</span>` : '';\n      return `<tr>\n        <td><strong>#${c.id}</strong></td>\n        <td>${caseBadge(c)}</td>\n        <td>${esc(c.userTag)}<span class=\"note\">${esc(c.userId)}</span></td>\n        <td>${esc(c.moderatorTag)}${c.auto ? ' 🤖' : ''}</td>\n        <td class=\"reason\">${esc(c.reason)}${c.note ? `<span class=\"note\">📝 ${esc(c.note)}</span>` : ''}</td>\n        <td>${duration}${expiry}</td>\n        <td>${esc(shortDate(c.createdAt))}</td>\n      </tr>`;\n    })\n    .join('');\n  return `<thead><tr><th>#</th><th>Typ</th><th>Użytkownik</th><th>Moderator</th><th>Powód</th><th>Czas</th><th>Data</th></tr></thead><tbody>${rows}</tbody>`;\n}\n\n// ---------- Formularze konfiguracji ----------\nfunction renderConfigUi() {\n  renderChannelSelects();\n  renderRoles();\n  renderRules();\n  renderActivities();\n  renderPermissions();\n  renderEmbedTabs();\n  fillInputs();\n  $('#emoji-picks').innerHTML = EMOJI_PICKS.map((e) => `<button type=\"button\" class=\"chip emoji\" data-emoji=\"${e}\">${e}</button>`).join('');\n  $('#presence-chips').innerHTML = PRESENCE_PLACEHOLDERS.map((p) => `<button type=\"button\" class=\"chip\" data-presence-placeholder=\"${p}\">${p}</button>`).join('');\n  $('#placeholder-chips').innerHTML = PLACEHOLDERS.map((p) => `<button type=\"button\" class=\"chip\" data-placeholder=\"${p}\">${p}</button>`).join('');\n  markDirty();\n}\n\nfunction fillInputs() {\n  $$('[data-path]').forEach((el) => {\n    const value = getPath(state.draft, el.dataset.path);\n    if (el.type === 'checkbox') el.checked = Boolean(value);\n    else el.value = value ?? '';\n  });\n  fillEmbedFields();\n}\n\nfunction readValue(el) {\n  if (el.type === 'checkbox') return el.checked;\n  if (el.type === 'number') return Math.max(0, Math.floor(Number(el.value) || 0));\n  return el.value;\n}\n\nfunction onFieldChange(event) {\n  const el = event.target;\n  if (el.dataset.path) {\n    setPath(state.draft, el.dataset.path, readValue(el));\n    markDirty();\n    if (el.dataset.path.startsWith('warns') || el.dataset.path === 'dmShowModerator' || el.dataset.path === 'appealText' || el.dataset.path === 'mentionTarget') {\n      renderPreview();\n    }\n  } else if (el.dataset.embedField) {\n    const field = el.dataset.embedField;\n    state.draft.actions[state.embedAction][field] = el.value;\n    if (field === 'color' && /^#[0-9a-f]{6}$/i.test(el.value)) $('#embed-color-picker').value = el.value;\n    renderEmbedTabs();\n    renderPreview();\n    markDirty();\n  }\n}\ndocument.addEventListener('input', onFieldChange);\ndocument.addEventListener('change', onFieldChange);\n\nfunction renderChannelSelects() {\n  $$('[data-channel-select]').forEach((select) => {\n    const current = getPath(state.draft, select.dataset.path) ?? '';\n    const emptyLabel = select.dataset.channelSelect === 'none' ? '— wyłączone —' : 'Kanał, na którym użyto komendy';\n    let html = `<option value=\"\">${emptyLabel}</option>`;\n    html += state.guild.channels\n      .map((c) => `<option value=\"${c.id}\">#${esc(c.name)}${c.category ? ` · ${esc(c.category)}` : ''}</option>`)\n      .join('');\n    if (current && !state.guild.channels.some((c) => c.id === current)) {\n      html += `<option value=\"${esc(current)}\">(nieznany kanał ${esc(current)})</option>`;\n    }\n    select.innerHTML = html;\n    select.value = current;\n  });\n}\n\nfunction renderRoles() {\n  const box = $('#roles-list');\n  if (!state.guild.roles.length) {\n    box.innerHTML = '<p class=\"muted small\">Brak ról do wyświetlenia — bot nie jest jeszcze połączony z serwerem.</p>';\n    return;\n  }\n  box.innerHTML = state.guild.roles\n    .map((role) => {\n      const color = role.color === '#000000' ? '#99aab5' : role.color;\n      const checked = state.draft.modRoleIds.includes(role.id) ? 'checked' : '';\n      return `<label class=\"role-item\"><input type=\"checkbox\" data-role=\"${role.id}\" ${checked}><span class=\"role-dot\" style=\"background:${esc(color)}\"></span>${esc(role.name)}</label>`;\n    })\n    .join('');\n}\n$('#roles-list').addEventListener('change', () => {\n  state.draft.modRoleIds = $$('[data-role]').filter((el) => el.checked).map((el) => el.dataset.role);\n  markDirty();\n});\n\n$('#emoji-picks').addEventListener('click', (event) => {\n  const emoji = event.target.closest('[data-emoji]')?.dataset.emoji;\n  if (!emoji) return;\n  state.draft.replyReaction.emoji = emoji;\n  fillInputs();\n  markDirty();\n});\n\n// ---------- Uprawnienia komend ----------\n// Ta sama logika co po stronie bota (moderation.js/roleHasAccess) — liczona tu, żeby pokazać\n// podgląd na żywo bez proszenia bota o każdą kombinację roli i komendy.\nconst ADMINISTRATOR_BIT = 8n;\nfunction hasBit(bitsStr, bit) {\n  const bits = BigInt(bitsStr || 0);\n  return (bits & bit) === bit;\n}\nfunction roleCanUseDefault(role, permission, modRoleIds) {\n  if (hasBit(role.permissions, ADMINISTRATOR_BIT)) return true;\n  if (!permission) return true;\n  if (hasBit(role.permissions, BigInt(permission))) return true;\n  return modRoleIds.includes(role.id);\n}\nfunction roleCanUse(role, cmd, config) {\n  if (hasBit(role.permissions, ADMINISTRATOR_BIT)) return true;\n  const override = config.commandPermissions?.[cmd.name];\n  if (Array.isArray(override)) return override.includes(role.id);\n  return roleCanUseDefault(role, cmd.permission, config.modRoleIds);\n}\n\nfunction renderPermissions() {\n  if (!state.commandMeta) return;\n  const roles = state.guild.roles;\n  const overrides = state.draft.commandPermissions ?? (state.draft.commandPermissions = {});\n\n  $('#permission-commands').innerHTML = state.commandMeta\n    .map((cmd) => {\n      const active = Array.isArray(overrides[cmd.name]);\n      const selected = new Set(active ? overrides[cmd.name] : roles.filter((r) => roleCanUseDefault(r, cmd.permission, state.draft.modRoleIds)).map((r) => r.id));\n      const roleChecks = roles\n        .map(\n          (r) => `<label class=\"role-item\"><input type=\"checkbox\" data-perm-role=\"${r.id}\" data-perm-cmd=\"${cmd.name}\" ${selected.has(r.id) ? 'checked' : ''} ${active ? '' : 'disabled'}><span class=\"role-dot\" style=\"background:${esc(r.color === '#000000' ? '#99aab5' : r.color)}\"></span>${esc(r.name)}</label>`,\n        )\n        .join('');\n      return `<div class=\"perm-command\" data-cmd=\"${cmd.name}\">\n        <div class=\"perm-command-head\">\n          <div><code>/${esc(cmd.name)}</code> <span class=\"muted small\">${esc(cmd.description)}</span></div>\n          <label class=\"toggle small\"><input type=\"checkbox\" data-perm-toggle=\"${cmd.name}\" ${active ? 'checked' : ''}><span></span>Ogranicz do wybranych ról</label>\n        </div>\n        <div class=\"muted small\">Domyślnie: ${esc(cmd.permissionLabel)}${state.draft.modRoleIds.length ? ' albo rola moderatora z Ustawień' : ''}</div>\n        <div class=\"roles-list compact\">${roleChecks || '<p class=\"muted small\">Brak ról na serwerze.</p>'}</div>\n      </div>`;\n    })\n    .join('');\n\n  renderPermissionMatrix();\n}\n\nfunction renderPermissionMatrix() {\n  const roles = state.guild.roles;\n  const cmds = state.commandMeta;\n  if (!roles?.length || !cmds?.length) {\n    $('#permission-matrix').innerHTML = '<tr><td class=\"empty\">Bot nie jest jeszcze połączony z serwerem — role pojawią się tutaj automatycznie.</td></tr>';\n    return;\n  }\n  const head = `<thead><tr><th>Rola</th>${cmds.map((c) => `<th title=\"${esc(c.description)}\">/${esc(c.name)}</th>`).join('')}</tr></thead>`;\n  const body = roles\n    .map((r) => {\n      const cells = cmds.map((c) => `<td class=\"perm-cell\">${roleCanUse(r, c, state.draft) ? '✅' : '—'}</td>`).join('');\n      return `<tr><td><span class=\"role-dot\" style=\"background:${esc(r.color === '#000000' ? '#99aab5' : r.color)}\"></span>${esc(r.name)}</td>${cells}</tr>`;\n    })\n    .join('');\n  $('#permission-matrix').innerHTML = head + `<tbody>${body}</tbody>`;\n}\n\n$('#permission-commands').addEventListener('change', (event) => {\n  const toggleName = event.target.dataset.permToggle;\n  if (toggleName) {\n    if (event.target.checked) {\n      const cmd = state.commandMeta.find((c) => c.name === toggleName);\n      state.draft.commandPermissions[toggleName] = state.guild.roles\n        .filter((r) => roleCanUseDefault(r, cmd.permission, state.draft.modRoleIds))\n        .map((r) => r.id);\n    } else {\n      delete state.draft.commandPermissions[toggleName];\n    }\n    renderPermissions();\n    markDirty();\n    return;\n  }\n  const roleId = event.target.dataset.permRole;\n  const cmdName = event.target.dataset.permCmd;\n  if (!roleId || !cmdName) return;\n  const list = state.draft.commandPermissions[cmdName] ?? [];\n  state.draft.commandPermissions[cmdName] = event.target.checked ? [...new Set([...list, roleId])] : list.filter((id) => id !== roleId);\n  renderPermissionMatrix();\n  markDirty();\n});\n\n// ---------- Progi automatycznych kar ----------\nconst optionList = (map, selected) =>\n  Object.entries(map).map(([value, label]) => `<option value=\"${value}\" ${value === selected ? 'selected' : ''}>${label}</option>`).join('');\n\nfunction renderRules() {\n  const rules = state.draft.escalation.rules;\n  const body = rules\n    .map((rule, i) => {\n      const noTime = rule.action === 'alert' || rule.action === 'kick';\n      return `<tr data-rule=\"${i}\">\n        <td><input type=\"number\" min=\"1\" value=\"${rule.points}\" data-rule-field=\"points\" aria-label=\"Próg punktów\"></td>\n        <td><select data-rule-field=\"action\" aria-label=\"Akcja\">${optionList(RULE_ACTIONS, rule.action)}</select></td>\n        <td><input type=\"number\" min=\"0\" value=\"${rule.amount}\" data-rule-field=\"amount\" aria-label=\"Czas\" ${noTime ? 'disabled' : ''}></td>\n        <td><select data-rule-field=\"unit\" aria-label=\"Jednostka\" ${noTime ? 'disabled' : ''}>${optionList(UNIT_LABELS, rule.unit)}</select></td>\n        <td><button type=\"button\" class=\"btn ghost small\" data-rule-del title=\"Usuń próg\">✕</button></td>\n      </tr>`;\n    })\n    .join('');\n  $('#rules-table').innerHTML = `<thead><tr><th>Próg (pkt)</th><th>Akcja</th><th>Czas</th><th>Jednostka</th><th></th></tr></thead>\n    <tbody>${body || '<tr><td colspan=\"5\" class=\"empty\">Brak progów</td></tr>'}</tbody>\n    <tfoot><tr><td colspan=\"5\" class=\"muted small\">Czas 0 przy banie = ban permanentny. Timeout: maks. 28 dni (0 = 28 dni).</td></tr></tfoot>`;\n}\n\nfunction onRuleChange(event) {\n  const row = event.target.closest('[data-rule]');\n  const field = event.target.dataset.ruleField;\n  if (!row || !field) return;\n  event.stopPropagation();\n  const rule = state.draft.escalation.rules[Number(row.dataset.rule)];\n  rule[field] = field === 'points' || field === 'amount' ? Math.max(0, Math.floor(Number(event.target.value) || 0)) : event.target.value;\n  if (field === 'action') renderRules();\n  markDirty();\n}\n$('#rules-table').addEventListener('input', onRuleChange);\n$('#rules-table').addEventListener('change', onRuleChange);\n$('#rules-table').addEventListener('click', (event) => {\n  const row = event.target.closest('[data-rule-del]') && event.target.closest('[data-rule]');\n  if (!row) return;\n  state.draft.escalation.rules.splice(Number(row.dataset.rule), 1);\n  renderRules();\n  markDirty();\n});\n$('#add-rule').addEventListener('click', () => {\n  const last = state.draft.escalation.rules.at(-1);\n  state.draft.escalation.rules.push({ points: (last?.points ?? 0) + 5, action: 'timeout', amount: 1, unit: 'h' });\n  renderRules();\n  markDirty();\n});\n\n// ---------- Status bota (opisy) ----------\nfunction renderActivities() {\n  const list = state.draft.presence.activities;\n  const body = list\n    .map(\n      (a, i) => `<tr data-activity=\"${i}\">\n        <td><select data-activity-field=\"type\" aria-label=\"Rodzaj\">${optionList(ACTIVITY_LABELS, a.type)}</select></td>\n        <td class=\"grow\"><input type=\"text\" maxlength=\"128\" value=\"${esc(a.text)}\" data-activity-field=\"text\" aria-label=\"Tekst opisu\"></td>\n        <td><button type=\"button\" class=\"btn ghost small\" data-activity-del title=\"Usuń opis\">✕</button></td>\n      </tr>`,\n    )\n    .join('');\n  $('#activities-table').innerHTML = `<thead><tr><th>Rodzaj</th><th>Tekst</th><th></th></tr></thead>\n    <tbody>${body || '<tr><td colspan=\"3\" class=\"empty\">Brak opisów — bot będzie tylko „online”.</td></tr>'}</tbody>`;\n  $('#add-activity').disabled = list.length >= 10;\n}\n\nfunction onActivityChange(event) {\n  const row = event.target.closest('[data-activity]');\n  const field = event.target.dataset.activityField;\n  if (!row || !field) return;\n  event.stopPropagation();\n  state.draft.presence.activities[Number(row.dataset.activity)][field] = event.target.value;\n  state.lastActivityInput = field === 'text' ? event.target : state.lastActivityInput;\n  markDirty();\n}\n$('#activities-table').addEventListener('input', onActivityChange);\n$('#activities-table').addEventListener('change', onActivityChange);\n$('#activities-table').addEventListener('focusin', (event) => {\n  if (event.target.dataset.activityField === 'text') state.lastActivityInput = event.target;\n});\n$('#activities-table').addEventListener('click', (event) => {\n  const row = event.target.closest('[data-activity-del]') && event.target.closest('[data-activity]');\n  if (!row) return;\n  state.draft.presence.activities.splice(Number(row.dataset.activity), 1);\n  state.lastActivityInput = null;\n  renderActivities();\n  markDirty();\n});\n$('#add-activity').addEventListener('click', () => {\n  state.draft.presence.activities.push({ type: 'custom', text: '🫓 ' });\n  renderActivities();\n  markDirty();\n  const inputs = $$('#activities-table [data-activity-field=\"text\"]');\n  inputs.at(-1)?.focus();\n});\n$('#presence-chips').addEventListener('click', (event) => {\n  const text = event.target.closest('[data-presence-placeholder]')?.dataset.presencePlaceholder;\n  const field = state.lastActivityInput?.isConnected ? state.lastActivityInput : $$('#activities-table [data-activity-field=\"text\"]').at(-1);\n  if (!text || !field) return;\n  const start = field.selectionStart ?? field.value.length;\n  const end = field.selectionEnd ?? field.value.length;\n  field.value = (field.value.slice(0, start) + text + field.value.slice(end)).slice(0, 128);\n  field.focus();\n  field.setSelectionRange(start + text.length, start + text.length);\n  field.dispatchEvent(new Event('input', { bubbles: true }));\n});\n\n// ---------- Hasło panelu ----------\nfunction renderPasswordStatus(status) {\n  const text = $('#password-status');\n  const form = $('#password-form');\n  if (!text || !form) return;\n  if (status.passwordFixed) {\n    text.textContent = 'Hasło jest ustawione na stałe przez sekret PANEL_PASSWORD w Supabase (Edge Functions → Secrets) — zmień je tam.';\n    form.classList.add('hidden');\n  } else {\n    text.textContent = 'Hasło zostało wygenerowane automatycznie i trzyma je bot w bazie. Możesz je tutaj zmienić na własne.';\n    form.classList.remove('hidden');\n  }\n}\n\n$('#password-form').addEventListener('submit', async (event) => {\n  event.preventDefault();\n  const next = $('#password-new').value;\n  const repeat = $('#password-repeat').value;\n  if (next !== repeat) return toast('Hasła nie są takie same.', 'error');\n  $('#password-submit').disabled = true;\n  try {\n    await api('/password', { method: 'POST', body: JSON.stringify({ next }) });\n    setPanelPassword(next);\n    $('#password-new').value = '';\n    $('#password-repeat').value = '';\n    toast('Hasło panelu zmienione ✅');\n  } catch (error) {\n    toast(error.message, 'error');\n  } finally {\n    $('#password-submit').disabled = false;\n  }\n});\n\nfunction renderGatewayLine(gateway) {\n  const line = $('#gateway-line');\n  if (!line) return;\n  if (!gateway?.startedAt) {\n    line.textContent = 'gateway: jeszcze nie połączony';\n    return;\n  }\n  const fresh = Date.now() - (gateway.endedAt ?? gateway.startedAt) < 3 * MINUTE;\n  const current = gateway.activity ? ` • „${gateway.activity}”` : '';\n  line.textContent = gateway.error\n    ? `🔴 ${gateway.error}`\n    : `${fresh ? '🟢' : '🟠'} gateway ${relTime(gateway.endedAt ?? gateway.startedAt)}${current}`;\n}\n\n// ---------- Zapis ----------\nfunction isDirty() {\n  return state.draft && JSON.stringify(state.draft) !== JSON.stringify(state.config);\n}\nfunction markDirty() {\n  $('#savebar').classList.toggle('hidden', !isDirty());\n}\n\n$('#save').addEventListener('click', async () => {\n  $('#save').disabled = true;\n  try {\n    const { config } = await api('/config', { method: 'PUT', body: JSON.stringify(state.draft) });\n    state.config = config;\n    state.draft = clone(config);\n    renderConfigUi();\n    renderPreview();\n    toast('Zapisano ustawienia ✅');\n  } catch (error) {\n    toast(error.message, 'error');\n  } finally {\n    $('#save').disabled = false;\n  }\n});\n\n$('#discard').addEventListener('click', () => {\n  state.draft = clone(state.config);\n  renderConfigUi();\n  renderPreview();\n});\n\nwindow.addEventListener('beforeunload', (event) => {\n  if (isDirty()) event.preventDefault();\n});\n\n// ---------- Edytor embedów ----------\nfunction renderEmbedTabs() {\n  $('#embed-tabs').innerHTML = Object.keys(ACTION_LABELS)\n    .map((action) => {\n      const style = state.draft.actions[action];\n      return `<button type=\"button\" class=\"tab ${action === state.embedAction ? 'active' : ''}\" data-action=\"${action}\" style=\"--tab-color:${esc(style.color)}\">${esc(style.emoji)} ${ACTION_LABELS[action]}</button>`;\n    })\n    .join('');\n}\n\nfunction fillEmbedFields() {\n  const style = state.draft.actions[state.embedAction];\n  $$('[data-embed-field]').forEach((el) => {\n    if (document.activeElement !== el) el.value = style[el.dataset.embedField] ?? '';\n  });\n  if (/^#[0-9a-f]{6}$/i.test(style.color)) $('#embed-color-picker').value = style.color;\n}\n\n$('#embed-tabs').addEventListener('click', (event) => {\n  const action = event.target.closest('[data-action]')?.dataset.action;\n  if (!action) return;\n  state.embedAction = action;\n  renderEmbedTabs();\n  fillEmbedFields();\n  renderPreview();\n});\n\n$('#embed-color-picker').addEventListener('input', (event) => {\n  event.stopPropagation();\n  const field = $('[data-embed-field=\"color\"]');\n  field.value = event.target.value.toUpperCase();\n  field.dispatchEvent(new Event('input', { bubbles: true }));\n});\n\ndocument.addEventListener('focusin', (event) => {\n  if (event.target.dataset?.embedField && event.target.dataset.embedField !== 'color') state.lastField = event.target;\n});\n\n$('#placeholder-chips').addEventListener('click', (event) => {\n  const text = event.target.closest('[data-placeholder]')?.dataset.placeholder;\n  const field = state.lastField ?? $('[data-embed-field=\"description\"]');\n  if (!text) return;\n  const start = field.selectionStart ?? field.value.length;\n  const end = field.selectionEnd ?? field.value.length;\n  field.value = field.value.slice(0, start) + text + field.value.slice(end);\n  field.focus();\n  field.setSelectionRange(start + text.length, start + text.length);\n  field.dispatchEvent(new Event('input', { bubbles: true }));\n});\n\n$('#embed-reset').addEventListener('click', () => {\n  state.draft.actions[state.embedAction] = clone(state.defaults.actions[state.embedAction]);\n  renderEmbedTabs();\n  $$('[data-embed-field]').forEach((el) => (el.value = state.draft.actions[state.embedAction][el.dataset.embedField] ?? ''));\n  fillEmbedFields();\n  renderPreview();\n  markDirty();\n});\n\n// Mini-markdown Discorda do podglądu.\nfunction md(text) {\n  const names = { [SAMPLE.targetId]: SAMPLE.target, [SAMPLE.modId]: SAMPLE.mod };\n  return String(text ?? '')\n    .split('\\n')\n    .map((raw) => {\n      let line = raw;\n      const small = line.startsWith('-# ');\n      if (small) line = line.slice(3);\n      const html = esc(line)\n        .replace(/&lt;(a?):(\\w+):(\\d+)&gt;/g, (_, a, name, id) => `<img class=\"emoji\" alt=\":${name}:\" src=\"https://cdn.discordapp.com/emojis/${id}.${a ? 'gif' : 'webp'}?size=48\">`)\n        .replace(/&lt;@!?(\\d+)&gt;/g, (_, id) => `<span class=\"mention\">@${esc(names[id] ?? 'użytkownik')}</span>`)\n        .replace(/&lt;t:(\\d+):([a-zA-Z])&gt;/g, (_, ts, style) => `<span class=\"ts\">${style === 'R' ? relTime(ts * 1000) : fullDate(ts * 1000)}</span>`)\n        .replace(/\\*\\*(.+?)\\*\\*/g, '<strong>$1</strong>')\n        .replace(/(^|[^*])\\*([^*\\s][^*]*)\\*/g, '$1<em>$2</em>')\n        .replace(/`([^`]+)`/g, '<code>$1</code>');\n      return small ? `<small>${html}</small>` : html;\n    })\n    .join('<br>');\n}\n\nconst ts = (ms, style) => `<t:${Math.floor(ms / 1000)}:${style}>`;\nconst withEmoji = (style, text) => {\n  const cleaned = String(text ?? '').replace(/\\s{2,}/g, ' ').trim();\n  return style.emoji ? `${style.emoji} ${cleaned}` : cleaned;\n};\n\n// Odzwierciedla supabase/functions/hopkostki-bot/lib/embeds.js — przykładowe dane do podglądu.\nfunction previewData(action) {\n  const cfg = state.draft;\n  const style = cfg.actions[action];\n  const now = Date.now();\n  const server = state.status?.guild?.name ?? 'Entuzjaści Hopkostki';\n  const brand = 'Entuzjaści Hopkostki 🫓';\n  const ctx = { duration: null, expiresAt: null, warn: null };\n  if (action === 'ban') Object.assign(ctx, { duration: '14 dni', expiresAt: now + 14 * DAY });\n  if (action === 'timeout') Object.assign(ctx, { duration: '2 godziny', expiresAt: now + 2 * HOUR });\n  if (action === 'warn') {\n    ctx.warn = { points: 2, count: 3, total: 5, expiresAt: cfg.warns.expiryDays > 0 ? now + cfg.warns.expiryDays * DAY : null };\n  }\n  const durationText = ctx.duration ?? (action === 'ban' ? 'Permanentny' : null);\n  const vars = {\n    uzytkownik: `<@${SAMPLE.targetId}>`,\n    nick: SAMPLE.target,\n    moderator: `<@${SAMPLE.modId}>`,\n    moderatorNick: SAMPLE.mod,\n    powod: SAMPLE.reason,\n    czas: durationText ?? '—',\n    serwer: server,\n    sprawa: '#42',\n    typ: action === 'ban' ? 'tymczasowo' : '',\n  };\n  const fill = (text) => String(text ?? '').replace(/\\{(\\w+)\\}/g, (m, key) => (key in vars ? vars[key] : m));\n  const stamp = (ms) => `${ts(ms, 'f')}\\n${ts(ms, 'R')}`;\n\n  const timeFields = [];\n  if (durationText) timeFields.push({ name: '⏱️ Czas trwania', value: `**${durationText}**`, inline: true });\n  if (ctx.expiresAt) timeFields.push({ name: '📅 Wygasa', value: stamp(ctx.expiresAt), inline: true });\n  const warnFields = (points, totals) => {\n    if (!ctx.warn) return [];\n    const fields = [];\n    if (points) fields.push({ name: '🔢 Punkty', value: `**+${ctx.warn.points}**${totals ? ` (razem **${ctx.warn.total}**)` : ''}`, inline: true });\n    if (ctx.warn.expiresAt) fields.push({ name: '⏳ Ostrzeżenie wygasa', value: stamp(ctx.warn.expiresAt), inline: true });\n    return fields;\n  };\n  const issued = { name: '🗓️ Nałożono', value: stamp(now), inline: true };\n  const reason = { name: '📝 Powód', value: SAMPLE.reason, code: true };\n  const showPoints = cfg.warns.showPointsToUser;\n\n  const channel = {\n    content: cfg.mentionTarget ? `<@${SAMPLE.targetId}>` : '',\n    author: `${server} • Moderacja`,\n    title: withEmoji(style, fill(style.title)),\n    description: fill(style.description).trim(),\n    fields: [\n      { name: '👤 Użytkownik', value: `<@${SAMPLE.targetId}>\\n\\`${SAMPLE.target}\\``, inline: true },\n      { name: '🛡️ Moderator', value: `<@${SAMPLE.modId}>`, inline: true },\n      ...timeFields,\n      issued,\n      ...warnFields(showPoints, false),\n      reason,\n    ],\n    footer: `Sprawa #42 • ${brand}`,\n    thumb: '🧑',\n  };\n\n  const dmFields = [...timeFields, issued, ...warnFields(showPoints, showPoints)];\n  if (cfg.dmShowModerator) dmFields.push({ name: '🛡️ Moderator', value: SAMPLE.mod, inline: true });\n  dmFields.push(reason);\n  if (cfg.appealText && ['ban', 'kick', 'timeout', 'warn'].includes(action)) dmFields.push({ name: '💬 Odwołania', value: cfg.appealText });\n  const dm = {\n    author: server,\n    title: withEmoji(style, fill(style.dmTitle)),\n    description: fill(style.dmDescription).trim(),\n    fields: dmFields,\n    footer: `Sprawa #42 • ${brand}`,\n    thumb: state.status?.guild?.icon ? { src: state.status.guild.icon } : '🫓',\n  };\n\n  return { color: style.color, channel, dm };\n}\n\n// Pola embeda jak w Discordzie: do 3 pól \"inline\" w rzędzie, pozostałe na całą szerokość.\nfunction fieldsHtml(fields = []) {\n  if (!fields.length) return '';\n  const items = fields\n    .map((f) => {\n      const value = f.code ? `<pre class=\"codeblock\">${esc(f.value)}</pre>` : md(f.value);\n      return `<div class=\"embed-field ${f.inline ? 'inline' : ''}\"><div class=\"embed-field-name\">${md(f.name)}</div><div class=\"embed-field-value\">${value}</div></div>`;\n    })\n    .join('');\n  return `<div class=\"embed-fields\">${items}</div>`;\n}\n\nfunction thumbHtml(thumb) {\n  if (!thumb) return '<div></div>';\n  if (thumb.src) return `<div class=\"embed-thumb\"><img src=\"${esc(thumb.src)}\" alt=\"\"></div>`;\n  return `<div class=\"embed-thumb\">${esc(thumb)}</div>`;\n}\n\nfunction messageHtml({ color, embed, content, slash }) {\n  const time = new Date().toLocaleTimeString('pl-PL', { hour: '2-digit', minute: '2-digit' });\n  const avatar = state.status?.bot?.avatar ? `<img src=\"${esc(state.status.bot.avatar)}\" alt=\"\">` : '🫓';\n  const name = state.status?.bot?.tag?.split('#')[0] ?? 'Entuzjaści Hopkostki';\n  const icon = state.status?.guild?.icon ? `<img class=\"embed-author-icon\" src=\"${esc(state.status.guild.icon)}\" alt=\"\">` : '';\n  return `<div class=\"msg\">\n    <div class=\"msg-avatar\">${avatar}</div>\n    <div>\n      ${slash ? `<div class=\"msg-reply\">↱ <b>${SAMPLE.mod}</b> użył <span class=\"mention\">${slash}</span></div>` : ''}\n      <div class=\"msg-head\"><span class=\"msg-name\">${esc(name)}</span><span class=\"msg-app\">APP</span><span class=\"msg-time\">Dzisiaj o ${time}</span></div>\n      ${content ? `<div>${md(content)}</div>` : ''}\n      <div class=\"embed\" style=\"border-left-color:${esc(color)}\">\n        <div>\n          ${embed.author ? `<div class=\"embed-author\">${icon}${esc(embed.author)}</div>` : ''}\n          <div class=\"embed-title\">${md(embed.title)}</div>\n          ${embed.description ? `<div class=\"embed-desc\">${md(embed.description)}</div>` : ''}\n          ${fieldsHtml(embed.fields)}\n        </div>\n        ${thumbHtml(embed.thumb)}\n        <div class=\"embed-footer\">${esc(embed.footer)} • Dzisiaj o ${time}</div>\n      </div>\n    </div>\n  </div>`;\n}\n\nfunction renderPreview() {\n  if (!state.draft || state.view !== 'embedy') return;\n  const data = previewData(state.embedAction);\n  $('#preview-channel').innerHTML = messageHtml({\n    color: data.color,\n    embed: data.channel,\n    content: data.channel.content,\n    slash: SLASH_NAMES[state.embedAction],\n  });\n  $('#preview-dm').innerHTML = state.draft.dmUsers\n    ? messageHtml({ color: data.color, embed: data.dm })\n    : '<p class=\"muted small\">Wysyłanie DM jest wyłączone w ustawieniach.</p>';\n}\n\n// ---------- Ostrzeżenia ----------\nasync function loadWarns() {\n  try {\n    const data = await api('/warns');\n    state.warnUsers = data.users;\n    renderWarns();\n  } catch (error) {\n    toast(error.message, 'error');\n  }\n}\n\nfunction lifeBar(w) {\n  if (!w.expiresAt) return '<span class=\"muted small\">♾️ nie wygasa</span>';\n  return `<div class=\"countdown\" data-expires=\"${w.expiresAt}\">${formatCountdown(w.expiresAt - Date.now())}</div>\n    <div class=\"lifebar\" title=\"Wygasa ${esc(fullDate(w.expiresAt))}\"><i data-created=\"${w.createdAt}\" data-until=\"${w.expiresAt}\"></i></div>`;\n}\n\nfunction renderWarns() {\n  const query = $('#warn-search').value.trim().toLowerCase();\n  const users = state.warnUsers.filter((u) => !query || u.userTag?.toLowerCase().includes(query) || u.userId.includes(query));\n  const scale = state.config.escalation.rules.at(-1)?.points ?? 10;\n\n  if (!users.length) {\n    $('#warn-users').innerHTML = `<p class=\"empty\">${query ? 'Nic nie znaleziono.' : 'Nikt nie ma aktywnych ostrzeżeń. 🎉'}</p>`;\n    return;\n  }\n  $('#warn-users').innerHTML = users\n    .map((u) => {\n      const ratio = u.points / scale;\n      const color = ratio >= 1 ? 'var(--red)' : ratio >= 0.5 ? '#f0883e' : 'var(--yellow)';\n      const rows = u.warns\n        .map(\n          (w) => `<div class=\"warn-row\">\n            <strong>#${w.id}</strong>\n            <span class=\"badge\" style=\"background:var(--yellow)\">${w.points} pkt</span>\n            <div class=\"reason\">${esc(w.reason)}<span class=\"note\">od ${esc(w.moderatorTag)} • ${esc(shortDate(w.createdAt))}</span></div>\n            <div>${lifeBar(w)}</div>\n            <button type=\"button\" class=\"btn danger small\" data-del-warn=\"${w.id}\">Usuń</button>\n          </div>`,\n        )\n        .join('');\n      return `<details class=\"warn-user\" data-user=\"${u.userId}\" ${state.openWarnUsers.has(u.userId) ? 'open' : ''}>\n        <summary>\n          <span class=\"who\">${esc(u.userTag)}</span>\n          <code>${esc(u.userId)}</code>\n          <span class=\"muted small\">${u.count} ${plural(u.count, ['ostrzeżenie', 'ostrzeżenia', 'ostrzeżeń'])}</span>\n          <span class=\"points\">${u.points} pkt</span>\n          <span class=\"severity\" title=\"${u.points}/${scale} pkt\"><i style=\"width:${Math.min(100, ratio * 100)}%;background:${color}\"></i></span>\n        </summary>\n        <div class=\"warn-list\">${rows}</div>\n      </details>`;\n    })\n    .join('');\n  tick();\n}\n\n$('#warn-search').addEventListener('input', (event) => {\n  event.stopPropagation();\n  renderWarns();\n});\n$('#warn-users').addEventListener(\n  'toggle',\n  (event) => {\n    const id = event.target.dataset?.user;\n    if (!id) return;\n    if (event.target.open) state.openWarnUsers.add(id);\n    else state.openWarnUsers.delete(id);\n  },\n  true,\n);\n$('#warn-users').addEventListener('click', async (event) => {\n  const id = event.target.closest('[data-del-warn]')?.dataset.delWarn;\n  if (!id || !confirm(`Usunąć ostrzeżenie #${id}?`)) return;\n  try {\n    await api(`/warns/${id}`, { method: 'DELETE' });\n    toast(`Usunięto ostrzeżenie #${id}`);\n    loadWarns();\n  } catch (error) {\n    toast(error.message, 'error');\n  }\n});\n\n// ---------- Sprawy ----------\nasync function loadCases() {\n  const params = new URLSearchParams({\n    page: state.casesPage,\n    limit: 25,\n    user: $('#case-search').value.trim(),\n    type: $('#case-type').value,\n  });\n  try {\n    const data = await api(`/cases?${params}`);\n    $('#cases-table').innerHTML = casesTable(data.items);\n    const pages = Math.max(1, Math.ceil(data.total / data.limit));\n    $('#cases-pager').innerHTML = `\n      <button type=\"button\" class=\"btn ghost small\" data-page=\"${data.page - 1}\" ${data.page <= 1 ? 'disabled' : ''}>← Nowsze</button>\n      <span class=\"muted small\">Strona ${data.page} z ${pages} • ${data.total} spraw</span>\n      <button type=\"button\" class=\"btn ghost small\" data-page=\"${data.page + 1}\" ${data.page >= pages ? 'disabled' : ''}>Starsze →</button>`;\n  } catch (error) {\n    toast(error.message, 'error');\n  }\n}\nlet caseSearchTimer = null;\n$('#case-search').addEventListener('input', (event) => {\n  event.stopPropagation();\n  clearTimeout(caseSearchTimer);\n  caseSearchTimer = setTimeout(() => {\n    state.casesPage = 1;\n    loadCases();\n  }, 300);\n});\n$('#case-type').addEventListener('change', (event) => {\n  event.stopPropagation();\n  state.casesPage = 1;\n  loadCases();\n});\n$('#cases-pager').addEventListener('click', (event) => {\n  const page = event.target.closest('[data-page]')?.dataset.page;\n  if (!page) return;\n  state.casesPage = Number(page);\n  loadCases();\n});\n\n// ---------- Tymczasowe bany ----------\nasync function loadBans() {\n  try {\n    const { bans } = await api('/tempbans');\n    const rows = bans\n      .map(\n        (b) => `<tr>\n          <td><strong>${esc(b.userTag)}</strong><span class=\"note\">${esc(b.userId)}</span></td>\n          <td><div class=\"countdown\" data-expires=\"${b.expiresAt}\">${formatCountdown(b.expiresAt - Date.now())}</div><span class=\"note\">${esc(fullDate(b.expiresAt))}</span></td>\n          <td>#${b.caseId}</td>\n          <td><button type=\"button\" class=\"btn success small\" data-unban=\"${esc(b.userId)}\">Odbanuj teraz</button></td>\n        </tr>`,\n      )\n      .join('');\n    $('#bans-table').innerHTML = bans.length\n      ? `<thead><tr><th>Użytkownik</th><th>Pozostało</th><th>Sprawa</th><th></th></tr></thead><tbody>${rows}</tbody>`\n      : '<tr><td class=\"empty\">Brak aktywnych tymczasowych banów.</td></tr>';\n  } catch (error) {\n    toast(error.message, 'error');\n  }\n}\n$('#bans-table').addEventListener('click', async (event) => {\n  const userId = event.target.closest('[data-unban]')?.dataset.unban;\n  if (!userId || !confirm('Zdjąć tego bana teraz?')) return;\n  try {\n    await api(`/tempbans/${userId}/unban`, { method: 'POST' });\n    toast('Ban zdjęty ✅');\n  } catch (error) {\n    toast(error.message, 'error');\n  }\n  loadBans();\n});\n\n// ---------- Odliczanie (co sekundę) ----------\nfunction tick() {\n  const now = Date.now();\n  let expired = false;\n  $$('[data-expires]').forEach((el) => {\n    const left = Number(el.dataset.expires) - now;\n    el.textContent = formatCountdown(left);\n    if (left <= 0) expired = true;\n  });\n  $$('[data-until]').forEach((el) => {\n    const created = Number(el.dataset.created);\n    const until = Number(el.dataset.until);\n    const left = Math.max(0, Math.min(1, (until - now) / (until - created)));\n    el.style.width = `${(left * 100).toFixed(2)}%`;\n  });\n  // Bot sprawdza wygasanie co 30 s — po chwili odświeżamy listę.\n  if (expired && !state.reloadPending) {\n    state.reloadPending = true;\n    setTimeout(() => {\n      state.reloadPending = false;\n      if (state.view === 'ostrzezenia') loadWarns();\n      if (state.view === 'bany') loadBans();\n    }, 35_000);\n  }\n}\n\nboot();\n";

export const PANEL_STYLE_CSS = ":root {\n  --bg: #313338;\n  --bg-2: #2b2d31;\n  --bg-3: #1e1f22;\n  --bg-hover: #35373c;\n  --line: #3f4147;\n  --text: #dbdee1;\n  --text-strong: #f2f3f5;\n  --muted: #949ba4;\n  --blurple: #5865f2;\n  --blurple-hover: #4752c4;\n  --green: #23a55a;\n  --red: #da373c;\n  --yellow: #f0b232;\n  --radius: 10px;\n  --font: 'gg sans', 'Noto Sans', 'Segoe UI', system-ui, -apple-system, sans-serif;\n}\n\n* { box-sizing: border-box; }\nhtml, body { margin: 0; }\nbody {\n  background: var(--bg);\n  color: var(--text);\n  font: 15px/1.45 var(--font);\n  -webkit-font-smoothing: antialiased;\n}\n.hidden { display: none !important; }\na { color: #00a8fc; }\ncode { background: var(--bg-3); padding: 1px 5px; border-radius: 4px; font-size: .88em; }\nh2, h3, h4 { color: var(--text-strong); margin: 0 0 .6rem; }\nh2 { font-size: 1.5rem; }\nh3 { font-size: 1.05rem; }\nh4 { font-size: .8rem; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); margin: 1rem 0 .4rem; }\n.muted { color: var(--muted); }\n.small { font-size: .85rem; }\n.error-text { color: var(--red); min-height: 1.2em; margin: 0; }\n\n/* ---------- Layout ---------- */\n.layout { display: grid; grid-template-columns: 240px 1fr; min-height: 100vh; }\n.sidebar {\n  background: var(--bg-2);\n  padding: 1rem .75rem;\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n  position: sticky;\n  top: 0;\n  height: 100vh;\n}\n.brand { display: flex; align-items: center; gap: .6rem; padding: .25rem .4rem .75rem; border-bottom: 1px solid var(--line); }\n.brand strong { display: block; color: var(--text-strong); }\n.logo { font-size: 1.8rem; }\n.logo.big { font-size: 3rem; }\n.state { font-size: .8rem; display: flex; align-items: center; gap: .35rem; }\n.state::before { content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--muted); }\n.state.online::before { background: var(--green); }\n.state.offline::before { background: var(--red); }\nnav { display: flex; flex-direction: column; gap: 2px; flex: 1; }\nnav a {\n  color: var(--muted);\n  text-decoration: none;\n  padding: .55rem .7rem;\n  border-radius: 6px;\n  display: flex;\n  gap: .55rem;\n}\nnav a:hover { background: var(--bg-hover); color: var(--text); }\nnav a.active { background: #404249; color: var(--text-strong); }\nmain { padding: 2rem clamp(1rem, 3vw, 2.5rem) 6rem; min-width: 0; }\n.view { display: none; max-width: 1200px; }\n.view.active { display: block; }\n.view-head { margin-bottom: 1.25rem; }\n.view-head p { margin: 0; }\n\n.grid { display: grid; gap: 1rem; margin-bottom: 1rem; }\n.grid.two { grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); }\n.grid.two.tight { gap: .75rem; margin-bottom: 0; grid-template-columns: 1fr 1fr; }\n.grid.editor { grid-template-columns: minmax(300px, 1fr) minmax(320px, 1.1fr); align-items: start; }\n\n.card {\n  background: var(--bg-2);\n  border-radius: var(--radius);\n  padding: 1.1rem 1.2rem;\n  margin-bottom: 1rem;\n  min-width: 0;\n}\n.grid > .card { margin-bottom: 0; }\n.card-head { display: flex; justify-content: space-between; align-items: center; gap: 1rem; flex-wrap: wrap; margin-bottom: .6rem; }\n.card-head h3 { margin: 0; }\n.row-card { display: flex; align-items: center; gap: 1rem; }\n.label { font-size: .75rem; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); font-weight: 700; }\n.big-text { font-size: 1.25rem; font-weight: 700; color: var(--text-strong); }\n.avatar { width: 38px; height: 38px; border-radius: 50%; object-fit: cover; }\n.avatar.lg { width: 64px; height: 64px; border-radius: 18px; }\n\n/* ---------- Statystyki ---------- */\n.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: .75rem; margin: 1rem 0; }\n.stat { background: var(--bg-2); border-radius: var(--radius); padding: .9rem 1rem; border-top: 3px solid var(--accent, var(--blurple)); }\n.stat b { display: block; font-size: 1.6rem; color: var(--text-strong); font-variant-numeric: tabular-nums; }\n.stat span { color: var(--muted); font-size: .85rem; }\n\n/* ---------- Formularze ---------- */\n.field { display: flex; flex-direction: column; gap: .3rem; margin-bottom: .85rem; }\n.field > span { font-size: .78rem; font-weight: 700; text-transform: uppercase; letter-spacing: .03em; color: var(--muted); }\n.field small { color: var(--muted); font-size: .8rem; }\ninput[type=text], input[type=password], input[type=number], input[type=search], select, textarea {\n  background: var(--bg-3);\n  color: var(--text);\n  border: 1px solid transparent;\n  border-radius: 6px;\n  padding: .55rem .7rem;\n  font: inherit;\n  width: 100%;\n  min-width: 0;\n}\ninput:focus, select:focus, textarea:focus { outline: none; border-color: var(--blurple); }\ntextarea { resize: vertical; }\n.color-row { display: flex; gap: .5rem; }\n.color-row input[type=color] { width: 44px; height: 40px; padding: 0; border: none; background: none; cursor: pointer; flex: none; }\n\n.toggle { display: flex; align-items: center; gap: .7rem; margin-bottom: .75rem; cursor: pointer; user-select: none; }\n.toggle input { display: none; }\n.toggle span {\n  width: 40px; height: 24px; border-radius: 12px; background: #80848e; position: relative; flex: none; transition: background .15s;\n}\n.toggle span::after {\n  content: ''; position: absolute; top: 3px; left: 3px; width: 18px; height: 18px; border-radius: 50%; background: #fff; transition: transform .15s;\n}\n.toggle input:checked + span { background: var(--green); }\n.toggle input:checked + span::after { transform: translateX(16px); }\n\n.btn {\n  border: none; border-radius: 6px; padding: .55rem 1rem; font: inherit; font-weight: 600; cursor: pointer;\n  color: #fff; background: #4e5058; transition: background .15s;\n}\n.btn:hover { background: #6d6f78; }\n.btn.primary { background: var(--blurple); }\n.btn.primary:hover { background: var(--blurple-hover); }\n.btn.success { background: var(--green); }\n.btn.success:hover { background: #1a8d4b; }\n.btn.danger { background: var(--red); }\n.btn.danger:hover { background: #a12828; }\n.btn.ghost { background: transparent; color: var(--text); border: 1px solid var(--line); }\n.btn.ghost:hover { background: var(--bg-hover); }\n.btn.small { padding: .3rem .6rem; font-size: .82rem; }\n.btn:disabled { opacity: .5; cursor: not-allowed; }\n\n.chips { display: flex; flex-wrap: wrap; gap: .4rem; margin-top: .4rem; }\n.chip {\n  background: var(--bg-3); color: var(--text); border: 1px solid var(--line); border-radius: 999px;\n  padding: .2rem .65rem; font: inherit; font-size: .85rem; cursor: pointer;\n}\n.chip:hover { border-color: var(--blurple); }\n.chip.emoji { font-size: 1.1rem; }\n.placeholders { margin: .5rem 0 1rem; }\n\n.roles-list { display: flex; flex-direction: column; gap: 2px; max-height: 260px; overflow-y: auto; }\n.role-item { display: flex; align-items: center; gap: .6rem; padding: .35rem .5rem; border-radius: 6px; cursor: pointer; }\n.role-item:hover { background: var(--bg-hover); }\n.role-dot { width: 12px; height: 12px; border-radius: 50%; flex: none; }\n\n/* ---------- Tabele ---------- */\n.table-wrap { overflow-x: auto; }\n.table { width: 100%; border-collapse: collapse; font-size: .9rem; }\n.table th { text-align: left; color: var(--muted); font-size: .75rem; text-transform: uppercase; letter-spacing: .04em; padding: .5rem; border-bottom: 1px solid var(--line); white-space: nowrap; }\n.table td { padding: .55rem .5rem; border-bottom: 1px solid var(--line); vertical-align: top; }\n.table tr:last-child td { border-bottom: none; }\n.table.compact td { padding: .35rem .3rem; }\n.table.compact input, .table.compact select { padding: .35rem .45rem; }\n#rules-table td:nth-child(1), #rules-table td:nth-child(3) { width: 84px; }\n#rules-table td:nth-child(2) { min-width: 150px; }\n#rules-table td:nth-child(4) { min-width: 120px; }\n#rules-table td:last-child { width: 1%; }\n.table .reason { max-width: 340px; overflow-wrap: anywhere; }\n.empty { color: var(--muted); text-align: center; padding: 1.5rem; }\n.badge { display: inline-block; padding: .1rem .5rem; border-radius: 4px; font-size: .78rem; font-weight: 700; color: #111; white-space: nowrap; }\n.note { display: block; color: var(--muted); font-size: .8rem; }\n.filters { display: flex; gap: .6rem; margin-bottom: .75rem; flex-wrap: wrap; }\n.filters input { flex: 1 1 220px; }\n.filters select { flex: 0 1 220px; }\n.pager { display: flex; justify-content: space-between; align-items: center; margin-top: .75rem; gap: .5rem; }\n\n/* ---------- Ostrzeżenia ---------- */\n#warn-search { max-width: 280px; }\n.warn-user { border: 1px solid var(--line); border-radius: 8px; margin-bottom: .6rem; overflow: hidden; }\n.warn-user summary {\n  list-style: none; cursor: pointer; display: flex; align-items: center; gap: .75rem; padding: .7rem .9rem; flex-wrap: wrap;\n}\n.warn-user summary::-webkit-details-marker { display: none; }\n.warn-user summary:hover { background: var(--bg-hover); }\n.warn-user[open] summary { border-bottom: 1px solid var(--line); }\n.warn-user .who { font-weight: 700; color: var(--text-strong); }\n.points { margin-left: auto; font-weight: 800; font-variant-numeric: tabular-nums; }\n.severity { width: 120px; height: 8px; background: var(--bg-3); border-radius: 4px; overflow: hidden; }\n.severity i { display: block; height: 100%; background: var(--yellow); }\n.warn-list { padding: .4rem .9rem .8rem; }\n.warn-row { display: grid; grid-template-columns: 60px 70px 1fr 220px auto; gap: .75rem; align-items: center; padding: .55rem 0; border-bottom: 1px dashed var(--line); }\n.warn-row:last-child { border-bottom: none; }\n.countdown { font-variant-numeric: tabular-nums; font-weight: 600; color: var(--text-strong); font-size: .88rem; }\n.lifebar { height: 5px; background: var(--bg-3); border-radius: 3px; overflow: hidden; margin-top: .3rem; }\n.lifebar i { display: block; height: 100%; background: linear-gradient(90deg, var(--green), var(--yellow)); }\n\n/* ---------- Zakładki + podgląd Discorda ---------- */\n.tabs { display: flex; gap: .4rem; flex-wrap: wrap; margin-bottom: 1rem; }\n.tab {\n  background: var(--bg-2); color: var(--muted); border: 1px solid transparent; border-radius: 8px;\n  padding: .5rem .9rem; font: inherit; font-weight: 600; cursor: pointer;\n}\n.tab:hover { color: var(--text); }\n.tab.active { color: var(--text-strong); border-color: var(--tab-color, var(--blurple)); background: var(--bg-hover); }\n\n.previews { position: sticky; top: 1rem; }\n.preview-label { font-size: .75rem; font-weight: 700; text-transform: uppercase; color: var(--muted); margin: 0 0 .4rem; }\n.discord { background: var(--bg); border: 1px solid var(--line); border-radius: var(--radius); padding: 1rem; margin-bottom: 1rem; }\n.msg { display: grid; grid-template-columns: 40px 1fr; gap: .9rem; }\n.msg-avatar { width: 40px; height: 40px; border-radius: 50%; background: var(--blurple); display: grid; place-items: center; font-size: 1.3rem; overflow: hidden; }\n.msg-avatar img { width: 100%; height: 100%; object-fit: cover; }\n.msg-head { display: flex; align-items: center; gap: .4rem; flex-wrap: wrap; }\n.msg-name { font-weight: 600; color: var(--text-strong); }\n.msg-app { background: var(--blurple); color: #fff; font-size: .62rem; font-weight: 700; padding: 1px 5px; border-radius: 3px; }\n.msg-time { color: var(--muted); font-size: .75rem; }\n.msg-reply { color: var(--muted); font-size: .85rem; margin-bottom: .2rem; }\n.mention { background: rgba(88, 101, 242, .3); color: #c9cdfb; border-radius: 3px; padding: 0 2px; font-weight: 500; }\n.ts { background: rgba(255, 255, 255, .06); border-radius: 3px; padding: 0 2px; }\n.embed {\n  margin-top: .3rem; background: var(--bg-2); border-left: 4px solid var(--blurple); border-radius: 4px;\n  max-width: 520px; padding: .6rem 1rem .9rem .8rem; display: grid; grid-template-columns: 1fr auto; gap: .5rem;\n}\n.embed-author { font-size: .85rem; font-weight: 600; color: var(--text-strong); display: flex; align-items: center; gap: .4rem; }\n.embed-title { font-weight: 700; color: var(--text-strong); margin: .15rem 0 .35rem; }\n.embed-desc { font-size: .9rem; overflow-wrap: anywhere; }\n.embed-desc small { color: var(--muted); font-size: .78rem; }\n.embed-thumb { width: 72px; height: 72px; border-radius: 6px; background: #4e5058; display: grid; place-items: center; font-size: 2rem; }\n.embed-footer { grid-column: 1 / -1; font-size: .75rem; color: var(--muted); margin-top: .2rem; }\n.embed-thumb img { width: 100%; height: 100%; object-fit: cover; border-radius: 6px; }\n.embed-author-icon { width: 20px; height: 20px; border-radius: 50%; }\n.embed-fields { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .5rem .9rem; margin-top: .55rem; }\n.embed-field { grid-column: 1 / -1; min-width: 0; }\n.embed-field.inline { grid-column: auto; }\n.embed-field-name { font-size: .82rem; font-weight: 700; color: var(--text-strong); margin-bottom: .1rem; }\n.embed-field-value { font-size: .88rem; overflow-wrap: anywhere; }\n.codeblock { margin: .15rem 0 0; padding: .45rem .6rem; background: #1e1f22; border: 1px solid #111214; border-radius: 4px; font-size: .82rem; white-space: pre-wrap; color: var(--text); }\n@media (max-width: 560px) { .embed-fields { grid-template-columns: 1fr; } }\n.embed img.emoji, .embed-title img.emoji { width: 1.2em; height: 1.2em; vertical-align: -.25em; }\n\n/* ---------- Połączenie, pasek zapisu, toast ---------- */\n.side-link { color: var(--muted); text-decoration: none; padding: .55rem .7rem; border-radius: 6px; }\n.side-link:hover { background: var(--bg-hover); color: var(--text); }\n.banner { background: rgba(218, 55, 60, .15); border: 1px solid var(--red); color: var(--text-strong); border-radius: 8px; padding: .8rem 1rem; margin-bottom: 1rem; }\n.checklist { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: .5rem; }\n.checklist li { display: grid; grid-template-columns: 1.6rem 1fr; gap: .4rem; align-items: start; }\n.checklist small { display: block; color: var(--muted); overflow-wrap: anywhere; }\n\n.savebar {\n  position: fixed; left: 50%; bottom: 1.2rem; transform: translateX(-50%);\n  width: min(720px, calc(100% - 2rem)); background: var(--bg-3); border-radius: 10px;\n  padding: .7rem .9rem .7rem 1.2rem; display: flex; justify-content: space-between; align-items: center; gap: 1rem;\n  box-shadow: 0 8px 24px rgba(0, 0, 0, .45); z-index: 20; animation: rise .2s ease-out;\n}\n.savebar div { display: flex; gap: .5rem; }\n@keyframes rise { from { transform: translate(-50%, 20px); opacity: 0; } }\n.toast {\n  position: fixed; top: 1rem; right: 1rem; background: var(--bg-3); color: var(--text-strong); padding: .7rem 1rem;\n  border-radius: 8px; border-left: 4px solid var(--green); box-shadow: 0 8px 24px rgba(0, 0, 0, .4);\n  transform: translateY(-20px); opacity: 0; visibility: hidden; transition: transform .25s, opacity .25s, visibility .25s;\n  z-index: 30; max-width: calc(100% - 2rem);\n}\n.toast.show { transform: none; opacity: 1; visibility: visible; }\n.toast.error { border-left-color: var(--red); }\n\n/* ---------- Telefon / wąskie okno ---------- */\n@media (max-width: 860px) {\n  .layout { grid-template-columns: 1fr; }\n  .sidebar { position: static; height: auto; flex-direction: row; flex-wrap: wrap; align-items: center; padding: .6rem; }\n  .brand { border: none; padding: 0; flex: 1; }\n  nav { flex-direction: row; overflow-x: auto; flex-basis: 100%; order: 3; }\n  nav a { white-space: nowrap; }\n  nav a span { display: none; }\n  nav a.active span { display: inline; }\n  main { padding: 1rem 1rem 6rem; }\n  .grid.editor, .grid.two.tight { grid-template-columns: 1fr; }\n  .previews { position: static; }\n  .warn-row { grid-template-columns: 1fr auto; }\n  .warn-row .reason { grid-column: 1 / -1; }\n}\n#activities-table td.grow { width: 100%; }\n#activities-table td.grow input { width: 100%; }\n#gateway-line { text-align: right; }\n\n/* ---------- Logowanie do panelu ---------- */\n.login-gate {\n  position: fixed; inset: 0; background: var(--bg); display: flex; align-items: center; justify-content: center;\n  padding: 1rem; z-index: 100;\n}\n.login-gate.hidden { display: none; }\n.login-card {\n  background: var(--bg-2); border-radius: var(--radius); padding: 2rem; width: min(380px, 100%);\n  text-align: center; box-shadow: 0 20px 60px rgba(0, 0, 0, .5);\n}\n.login-card .logo { margin-bottom: .5rem; }\n.login-card h2 { font-size: 1.2rem; }\n.login-card p { margin: 0 0 1rem; }\n.login-card input { margin-bottom: .6rem; text-align: center; }\n.login-card .btn { width: 100%; margin-top: .3rem; }\nbutton.side-link { background: none; border: none; font: inherit; text-align: left; width: 100%; cursor: pointer; }\n\n/* ---------- Uprawnienia ---------- */\n.perm-command { border: 1px solid var(--line); border-radius: 8px; padding: .8rem .9rem; margin-bottom: .6rem; }\n.perm-command:last-child { margin-bottom: 0; }\n.perm-command-head { display: flex; justify-content: space-between; align-items: center; gap: 1rem; flex-wrap: wrap; margin-bottom: .3rem; }\n.perm-command-head code { font-size: .95rem; }\n.toggle.small { font-size: .82rem; margin: 0; gap: .5rem; }\n.toggle.small span { width: 32px; height: 19px; }\n.toggle.small span::after { width: 13px; height: 13px; }\n.toggle.small input:checked + span::after { transform: translateX(13px); }\n.roles-list.compact { max-height: 140px; margin-top: .5rem; flex-direction: row; flex-wrap: wrap; gap: .3rem .8rem; }\n.roles-list.compact .role-item { padding: .15rem 0; }\n#permission-matrix th, #permission-matrix td { text-align: center; }\n#permission-matrix th:first-child, #permission-matrix td:first-child { text-align: left; white-space: nowrap; }\n#permission-matrix td:first-child .role-dot { display: inline-block; margin-right: .4rem; vertical-align: middle; }\n.perm-cell { font-size: 1rem; }\n";
